import{_ as t,o as h,c as o,a3 as a}from"./chunks/framework.DX_KL3e0.js";const g="/help/screenshots/nhan-su/tong-quan.png",p=JSON.parse('{"title":"Quản Lý Hồ Sơ (C&B)","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/nhan-su.md","filePath":"chuc-nang/nhan-su.md","lastUpdated":1781776232000}'),i={name:"chuc-nang/nhan-su.md"};function r(c,n,s,e,l,u){return h(),o("div",null,[...n[0]||(n[0]=[a('<h1 id="quan-ly-ho-so-c-b" tabindex="-1">Quản Lý Hồ Sơ (C&amp;B) <a class="header-anchor" href="#quan-ly-ho-so-c-b" aria-label="Permalink to &quot;Quản Lý Hồ Sơ (C&amp;B)&quot;">​</a></h1><p>Module <strong>Quản Lý Hồ Sơ</strong> là khu vực nghiệp vụ Compensation &amp; Benefits: quản lý hợp đồng lao động, nhắc gia hạn tự động, lưu trữ hồ sơ – giấy tờ nhân sự và đánh giá thử việc.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/nhan-su</code> (menu <strong>Quản Lý Hồ Sơ</strong>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin (mặc định không có quyền Xóa). Quản lý / Người dùng cần được cấp quyền module <code>hr</code>.</li><li><strong>4 thẻ chức năng:</strong> Tổng quan · Hợp đồng · Đánh giá · Hồ sơ. Thẻ <strong>Cài đặt</strong> chỉ hiện với <strong>Quản trị tối cao</strong>.</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Không có quyền xem?</p><p>Nếu tài khoản không có quyền <code>Xem</code> trên module <code>hr</code>, trang sẽ báo <em>&quot;Bạn không có quyền truy cập module Quản Lý Hồ Sơ&quot;</em>. Khi đó bạn vẫn xem được hợp đồng &amp; hồ sơ của riêng mình ở trang <a href="/help/chuc-nang/ho-so-cua-toi.html">Hồ sơ của tôi</a>.</p></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+g+'" alt="Trang Quản lý Hồ sơ (Nhân sự)"></p><p>Trang được tổ chức thành các tab; mỗi tab là một mảng nghiệp vụ riêng:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Dùng để</th></tr></thead><tbody><tr><td><strong>Tổng quan</strong></td><td>Thống kê hợp đồng và danh sách hợp đồng cần chú ý gia hạn.</td></tr><tr><td><strong>Hợp đồng</strong></td><td>Danh sách &amp; lịch sử hợp đồng lao động của nhân viên.</td></tr><tr><td><strong>Đánh giá</strong></td><td>Thẻ đánh giá kết thúc thử việc.</td></tr><tr><td><strong>Hồ sơ</strong></td><td>Lưu trữ tài liệu, giấy tờ nhân sự đính kèm.</td></tr><tr><td><strong>Cài đặt</strong></td><td>Người nhận thông báo Quản Lý Hồ Sơ, cấu hình loại hợp đồng, loại hồ sơ, hình thức làm việc (<strong>chỉ Quản trị tối cao</strong>).</td></tr></tbody></table><h2 id="tab-tong-quan" tabindex="-1">Tab Tổng quan <a class="header-anchor" href="#tab-tong-quan" aria-label="Permalink to &quot;Tab Tổng quan&quot;">​</a></h2><p>Hiển thị 4 thẻ thống kê: <strong>Tổng hợp đồng</strong>, <strong>Sắp hết hạn (≤30 ngày)</strong>, <strong>Đã quá hạn</strong>, <strong>Vô thời hạn</strong>. Bên dưới là danh sách <strong>Cần chú ý gia hạn</strong> — gồm hợp đồng đã quá hạn hoặc sắp hết hạn trong 30 ngày, sắp theo mức độ gấp.</p><h2 id="tab-hop-đong" tabindex="-1">Tab Hợp đồng <a class="header-anchor" href="#tab-hop-đong" aria-label="Permalink to &quot;Tab Hợp đồng&quot;">​</a></h2><h3 id="them-hop-đong-moi" tabindex="-1">Thêm hợp đồng mới <a class="header-anchor" href="#them-hop-đong-moi" aria-label="Permalink to &quot;Thêm hợp đồng mới&quot;">​</a></h3><ol><li>Vào tab <strong>Hợp đồng</strong>, nhấn <strong>Thêm mới</strong> (cần quyền <code>Thêm</code>).</li><li>Chọn nhân viên, loại hợp đồng, số hợp đồng, ngày ký / hiệu lực / hết hạn, thông tin lương, ghi chú.</li><li>Nhấn <strong>Lưu</strong>. Hợp đồng để trống <strong>ngày hết hạn</strong> được hiểu là <strong>vô thời hạn</strong>.</li></ol><h3 id="nhac-gia-han" tabindex="-1">Nhắc gia hạn <a class="header-anchor" href="#nhac-gia-han" aria-label="Permalink to &quot;Nhắc gia hạn&quot;">​</a></h3><p>Hệ thống tự đánh dấu hợp đồng <strong>sắp hết hạn</strong> (còn ≤30 ngày) và <strong>quá hạn</strong> để theo dõi ở tab Tổng quan. Trạng thái hợp đồng gồm: Nháp, Chờ ký, Hiệu lực, Đã gia hạn, Đã chấm dứt.</p><h3 id="đinh-kem-nguoi-theo-doi" tabindex="-1">Đính kèm &amp; người theo dõi <a class="header-anchor" href="#đinh-kem-nguoi-theo-doi" aria-label="Permalink to &quot;Đính kèm &amp; người theo dõi&quot;">​</a></h3><p>Trong chi tiết hợp đồng, bạn có thể đính kèm tệp scan và thêm <strong>người theo dõi</strong> để nhận thông báo gia hạn.</p><h3 id="tu-đong-tao-thoa-thuan-cho-nhan-su-moi" tabindex="-1">Tự động tạo thỏa thuận cho nhân sự mới <a class="header-anchor" href="#tu-đong-tao-thoa-thuan-cho-nhan-su-moi" aria-label="Permalink to &quot;Tự động tạo thỏa thuận cho nhân sự mới&quot;">​</a></h3><p>Trước <strong>ngày vào làm 1 ngày</strong>, hệ thống tự tạo sẵn <strong>bản nháp</strong> hai thỏa thuận cho nhân sự mới: <em>Thỏa thuận hợp tác</em> và <em>Thỏa thuận bảo mật thông tin (NDA)</em>. Bản nháp nằm ở tab Hợp đồng (trạng thái Nháp), C&amp;B hoàn thiện nội dung và ký.</p><p>Mỗi lần tạo nháp, hệ thống gửi thông báo (in-app + Telegram) cho <strong>người nhận thông báo Quản Lý Hồ Sơ</strong> (cấu hình ở tab Cài đặt) và những <strong>người theo dõi</strong> đã gắn cho hợp đồng đó.</p><h2 id="tab-đanh-gia-thu-viec" tabindex="-1">Tab Đánh giá (thử việc) <a class="header-anchor" href="#tab-đanh-gia-thu-viec" aria-label="Permalink to &quot;Tab Đánh giá (thử việc)&quot;">​</a></h2><p>Quản lý thẻ đánh giá kết thúc thử việc.</p><div class="tip custom-block"><p class="custom-block-title">Tự động tạo</p><p>Hệ thống tự sinh thẻ đánh giá khi nhân viên còn <strong>7 ngày</strong> là hết thử việc (thẻ có nhãn <strong>Auto</strong>). Bạn cũng có thể bấm <strong>Tạo đánh giá</strong> để tạo thủ công.</p></div><p>Trạng thái thẻ đánh giá: Nháp → Chờ đánh giá → Đã đánh giá → <strong>Đạt</strong> / <strong>Không đạt</strong> / <strong>Đã gia hạn TV</strong>.</p><ul><li>Thẻ đang ở trạng thái <em>Chờ đánh giá</em> / <em>Đã đánh giá</em> hiển thị badge <strong>hạn còn lại</strong> (đỏ khi ≤3 ngày hoặc quá hạn).</li><li>Lọc theo trạng thái và hình thức lao động; tìm theo tên nhân viên.</li><li>Chỉ xóa được thẻ <strong>chưa kết luận</strong> (chưa Đạt/Không đạt) và phải có quyền <code>Xóa</code>.</li></ul><h2 id="tab-ho-so" tabindex="-1">Tab Hồ sơ <a class="header-anchor" href="#tab-ho-so" aria-label="Permalink to &quot;Tab Hồ sơ&quot;">​</a></h2><p>Lưu trữ tài liệu nhân sự theo hai chế độ xem: <strong>Theo nhân viên</strong> (chọn 1 nhân viên để xem toàn bộ giấy tờ) và <strong>Tất cả</strong> (toàn bộ hồ sơ).</p><h3 id="tai-ho-so-len" tabindex="-1">Tải hồ sơ lên <a class="header-anchor" href="#tai-ho-so-len" aria-label="Permalink to &quot;Tải hồ sơ lên&quot;">​</a></h3><ol><li>Chọn chế độ <strong>Theo nhân viên</strong> và chọn nhân viên (hoặc chế độ <strong>Tất cả</strong>).</li><li>Nhấn <strong>Tải lên</strong> (một tệp) hoặc <strong>Tải lên đồng loạt</strong> (nhiều tệp). Cần quyền <code>Sửa</code>.</li><li>Chọn loại hồ sơ, đặt tiêu đề, chọn tệp rồi lưu.</li></ol><h3 id="thao-tac-khac" tabindex="-1">Thao tác khác <a class="header-anchor" href="#thao-tac-khac" aria-label="Permalink to &quot;Thao tác khác&quot;">​</a></h3><ul><li><strong>Xem trước</strong> ngay trong app với PDF, ảnh, Word, Excel/CSV.</li><li><strong>Tải xuống</strong> / <strong>Xóa</strong> từng tệp; ở chế độ <strong>Tất cả</strong> có thể chọn nhiều để <strong>tải / xóa hàng loạt</strong>.</li><li><strong>Yêu cầu đổi hồ sơ</strong>: nhân viên gửi yêu cầu thay tệp, người có quyền <code>Sửa</code> duyệt ngay trong tab.</li></ul><h2 id="tab-cai-đat" tabindex="-1">Tab Cài đặt <a class="header-anchor" href="#tab-cai-đat" aria-label="Permalink to &quot;Tab Cài đặt&quot;">​</a></h2><p>Chỉ hiện với <strong>Quản trị tối cao</strong>. Gồm:</p><ul><li><strong>Người Nhận Thông Báo Quản Lý Hồ Sơ</strong> — chọn các tài khoản nhận thông báo (in-app + Telegram) cho các sự kiện hồ sơ, ví dụ bản nháp thỏa thuận tự tạo cho nhân sự mới. Để trống = không ai nhận thông báo chung (chỉ còn người theo dõi riêng từng hợp đồng). Người trong danh sách nhưng tắt &quot;Bật Thông Báo&quot; ở Phân Quyền sẽ không nhận.</li><li><strong>Loại hợp đồng</strong>, <strong>loại hồ sơ</strong>, <strong>hình thức làm việc</strong> (đánh dấu hình thức nào cần đánh giá thử việc).</li></ul><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Vì sao một số tệp không có nút Xem trước?</strong> Chỉ các định dạng PDF, ảnh, Word, Excel/CSV mới xem trước được; định dạng khác chỉ có thể tải xuống.</p><p><strong>Đánh giá thử việc tự tạo khi nào?</strong> Khi còn 7 ngày là hết hạn thử việc, áp dụng cho các hình thức lao động được cấu hình <em>yêu cầu đánh giá</em>.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/nguon-nhan-luc.html">Nguồn Nhân Lực</a> · <a href="/help/chuc-nang/bieu-mau.html">Biểu mẫu</a> · <a href="/help/chuc-nang/lich-su.html">Lịch sử</a></p>',39)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
